import csv
import io
import sqlite3
import sys
import urllib.request


def fetch_csv(url):
    with urllib.request.urlopen(url, timeout=20) as response:
        return response.read().decode("utf-8")


def import_csv(db_path, text):
    with sqlite3.connect(db_path) as conn:
        for row in csv.DictReader(io.StringIO(text)):
            conn.execute("INSERT INTO billing(billing_id, amount, billing_date) VALUES (?, ?, ?)",
                         (row["billing_id"], row["amount"], row["billing_date"]))
            conn.commit()


def main(argv):
    if len(argv) != 3:
        raise SystemExit("usage: import_billing.py URL DB")
    import_csv(argv[2], fetch_csv(argv[1]))


if __name__ == "__main__":
    main(sys.argv)

