import json
import urllib.error
import urllib.request


def get_ticket(base_url, ticket_id):
    url = base_url.rstrip("/") + "/tickets/" + str(ticket_id)
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        if error.code == 404:
            return None
        raise

